style.css:
@-moz-document domain("github.com") {
html[data-color-mode][data-light-theme],
  html[data-color-mode][data-dark-theme] {

    /* Fondos */
    bgColor-default: #fff0f6 !important;
    bgColor-muted: #ffe3ef !important;
    bgColor-inset: #ffd6e7 !important;
    color-canvas-default: #fff0f6 !important;
    color-canvas-subtle: #ffe3ef !important;
    color-canvas-inset: #ffd6e7 !important;
    header-bgColor: #ff6fa5 !important;

    /* Texto */
    fgColor-default: #4a1230 !important;
    fgColor-muted: #8a3f66 !important;
    color-fg-default: #4a1230 !important;
    color-fg-muted: #8a3f66 !important;

    /* Bordes */
    borderColor-default: #f5a9c8 !important;
    borderColor-muted: #fbc8dc !important;
    color-border-default: #f5a9c8 !important;
    color-border-muted: #fbc8dc !important;

    /* Enlaces y acentos */
    -fgColor-accent: #d6336c !important;
    -color-accent-fg: #d6336c !important;
    -bgColor-accent-emphasis: #e64980 !important;
    -borderColor-accent-emphasis: #e64980 !important;
    -bgColor-accent-muted: #ffdeeb !important;

    /* Botón principal (verde por defecto) */
    -button-primary-bgColor-rest: #e64980 !important;
    -button-primary-bgColor-hover: #d6336c !important;
    -button-primary-borderColor-rest: #d6336c !important;
    -bgColor-success-emphasis: #e64980 !important;
  }

  /* Ajuste extra: selección de texto */
  ::selection {
    background: #ff8fb8;
    color: #fff;
  }
}
